const response = $input.first().json;
if (response.statusCode !== 200 || !Array.isArray(response.body)) throw new Error('Expected a successful Apify dataset response. Inspect the run before retrying.');
const seen = new Set($('Read existing jobs').all().map(i => String(i.json.jobUrl || '').trim()));
const safe = value => { const s = String(value ?? '').replace(/[\x00-\x1f]/g, ' ').slice(0, 1000); return /^[=+@-]/.test(s.trimStart()) ? "'" + s : s; };
const rows = [];
for (const job of response.body) {
  if (!job || typeof job.title !== 'string' || !job.title.trim() || typeof job.jobUrl !== 'string') throw new Error('Unexpected job schema; no rows written.');
  let url; try { url = new URL(job.jobUrl); } catch { throw new Error('Invalid job URL; no rows written.'); }
  if (!['https:', 'http:'].includes(url.protocol) || url.username || url.password) throw new Error('Unsafe job URL; no rows written.');
  url.hash = '';
  const key = url.href;
  if (seen.has(key)) continue;
  seen.add(key);
  rows.push({ json: { jobUrl: key, title: safe(job.title), company: safe(job.company), location: safe(job.location), jobBoard: safe(job.jobBoard), collectedAt: new Date().toISOString() } });
}
return rows;

const config = $input.first().json;
if (!config.searchTerm.trim() || !config.location.trim()) throw new Error('Set a search term and location.');
if (!/^[a-zA-Z0-9_-]{20,}$/.test(config.sheetId) || config.sheetId.includes('REPLACE_WITH')) throw new Error('Replace sheetId with your Google spreadsheet ID, not its full URL.');
if (!Array.isArray(config.jobBoards) || !config.jobBoards.length || config.jobBoards.some(board => !['indeed', 'linkedin'].includes(board))) throw new Error('Choose indeed, linkedin, or both.');
return [{ json: config }];
